package info.deltaindices.volumecamera;
import android.app.*;import android.content.*;import android.net.Uri;import android.os.*;import android.provider.MediaStore;import androidx.camera.core.*;import androidx.camera.lifecycle.ProcessCameraProvider;import androidx.core.content.ContextCompat;import androidx.lifecycle.LifecycleService;import com.google.common.util.concurrent.ListenableFuture;import java.text.SimpleDateFormat;import java.util.*;import java.util.concurrent.*;

public final class CaptureService extends LifecycleService {
 static final String ACTION_START="info.deltaindices.volumecamera.capture.START",ACTION_STOP="info.deltaindices.volumecamera.capture.STOP",ACTION_COUNT="info.deltaindices.volumecamera.capture.COUNT";
 private final Handler handler=new Handler(Looper.getMainLooper());private final ExecutorService io=Executors.newSingleThreadExecutor();private ImageCapture capture;private ProcessCameraProvider provider;private boolean stopping=false;
 private final Runnable cycle=new Runnable(){public void run(){take();}};
 @Override public void onCreate(){super.onCreate();startForeground(Notifications.CAPTURE_ID,Notifications.build(this,"Camera capture active","Rear camera · flash off · every "+Settings.interval(this)+" seconds",true));Settings.prefs(this).edit().putBoolean(Settings.CAPTURE_ACTIVE,true).putInt(Settings.SESSION_COUNT,0).apply();broadcastCount();bindCamera();}
 @Override public int onStartCommand(Intent intent,int flags,int id){super.onStartCommand(intent,flags,id);if(intent!=null&&ACTION_STOP.equals(intent.getAction())){stopCapture();return START_NOT_STICKY;}return START_NOT_STICKY;}
 private void bindCamera(){ListenableFuture<ProcessCameraProvider> future=ProcessCameraProvider.getInstance(this);future.addListener(()->{try{provider=future.get();capture=new ImageCapture.Builder().setFlashMode(ImageCapture.FLASH_MODE_OFF).setCaptureMode(ImageCapture.CAPTURE_MODE_MINIMIZE_LATENCY).build();provider.unbindAll();provider.bindToLifecycle(this,CameraSelector.DEFAULT_BACK_CAMERA,capture);handler.post(cycle);}catch(Exception e){stopCapture();}},ContextCompat.getMainExecutor(this));}
 private void take(){if(stopping||capture==null)return;String name="VC_"+new SimpleDateFormat("yyyyMMdd_HHmmss_SSS",Locale.US).format(new Date())+".jpg";ContentValues values=new ContentValues();values.put(MediaStore.Images.Media.DISPLAY_NAME,name);values.put(MediaStore.Images.Media.MIME_TYPE,"image/jpeg");if(Build.VERSION.SDK_INT>=29)values.put(MediaStore.Images.Media.RELATIVE_PATH,"DCIM/VolumeCamera");ImageCapture.OutputFileOptions options=new ImageCapture.OutputFileOptions.Builder(getContentResolver(),MediaStore.Images.Media.EXTERNAL_CONTENT_URI,values).build();capture.takePicture(options,io,new ImageCapture.OnImageSavedCallback(){public void onImageSaved(ImageCapture.OutputFileResults out){Uri uri=out.getSavedUri();if(uri!=null){DriveSync.enqueue(CaptureService.this,uri,name);int count=Settings.prefs(CaptureService.this).getInt(Settings.SESSION_COUNT,0)+1;Settings.prefs(CaptureService.this).edit().putInt(Settings.SESSION_COUNT,count).apply();broadcastCount();}handler.postDelayed(cycle,Settings.interval(CaptureService.this)*1000L);}public void onError(ImageCaptureException e){handler.postDelayed(cycle,Settings.interval(CaptureService.this)*1000L);}});}
 private void broadcastCount(){Intent event=new Intent(ACTION_COUNT).setPackage(getPackageName()).putExtra("count",Settings.prefs(this).getInt(Settings.SESSION_COUNT,0)).putExtra("active",Settings.prefs(this).getBoolean(Settings.CAPTURE_ACTIVE,false));sendBroadcast(event);}
 private void stopCapture(){if(stopping)return;stopping=true;handler.removeCallbacksAndMessages(null);if(provider!=null)provider.unbindAll();Settings.prefs(this).edit().putBoolean(Settings.CAPTURE_ACTIVE,false).apply();broadcastCount();stopForeground(STOP_FOREGROUND_REMOVE);stopSelf();}
 @Override public void onDestroy(){handler.removeCallbacksAndMessages(null);if(provider!=null)provider.unbindAll();io.shutdown();Settings.prefs(this).edit().putBoolean(Settings.CAPTURE_ACTIVE,false).apply();broadcastCount();super.onDestroy();}
}
